    slug: "caso-nvidia-trump-diz-que-toda-chinesa-bonita-vira-suspeita-de-espionagem",
    titulo: "Caso Nvidia: Trump diz que toda chinesa bonita vira suspeita de espionagem",
    categoria: "Tecnologia",
    data: "2026-11-16",
    imagem: "https://noticiaes.com.br/imagens/lapis/caso-nvidia-trump-diz-que-toda-chinesa-bonita-vira-suspeita-de-espionagem.jpg",
